import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { GameDataIndex, parseGameData } from './load';

// The committed fixture is generated by `dsp-extract fixture`; this is the app-side check that the
// Python normalizer and the zod schema agree.
const fixturePath = fileURLToPath(new URL('../../../../data/fixture/dsp-fixture.json', import.meta.url));

describe('data/fixture/dsp-fixture.json', () => {
  const json: unknown = JSON.parse(readFileSync(fixturePath, 'utf8'));
  const data = parseGameData(json, 'dsp-fixture.json');
  const index = new GameDataIndex(data);

  it('parses against the zod schema', () => {
    expect(data.meta.source).toBe('fixture');
    expect(data.meta.schemaVersion).toBe(1);
    expect(data.recipes.length).toBeGreaterThanOrEqual(160);
  });

  it('has the Processor recipe with its inputs and output', () => {
    const processor = index.recipe(51);
    expect(processor.timeTicks).toBe(180);
    expect(processor.inputs).toEqual([
      { itemId: 1301, count: 2 },
      { itemId: 1302, count: 2 },
    ]);
    expect(processor.outputs).toEqual([{ itemId: 1303, count: 1 }]);
  });

  it('marks every building geometry approximate', () => {
    expect(data.buildings.length).toBeGreaterThan(0);
    expect(data.buildings.every((b) => b.geometry.source === 'approximate')).toBe(true);
  });

  it('indexes assemblers and stations', () => {
    expect(index.building(2303)?.production).toEqual({ recipeType: 'ASSEMBLE', speed: 7500 });
    expect(index.building(2104)?.station?.maxItemKinds).toBe(5);
    expect(index.buildingsForRecipeType('SMELT').map((b) => b.itemId)).toContain(2302);
    expect(index.item(1141).proliferator).toEqual({ ability: 1, sprays: 12 });
  });
});
